r = r_plus.detach().numpy().astype(np.float64)
acts = {}
for L in range(24):
    acts[L] = np.load(f'/work/fwd_2/mlp_act_L{L}.npy').astype(np.float64)  # [text, pos, 3584]
meta = json.load(open('/work/fwd_2/meta.json')); lengths = meta['lengths']; tids = meta['token_ids']
coef = {}
for L in range(24):
    W = load(f'model.language_model.layers.{L}.mlp.down_proj.weight').float().numpy().astype(np.float64)  # [1024,3584]
    coef[L] = r @ W  # [3584]
    del W

def dla(L, ti, p):
    return float(acts[L][ti, p] @ coef[L])
